function processAndSavePhoto($uploadedFile, $nip, $dbConnection) {
  $allowedExtensions = array('jpg', 'jpeg', 'png', 'gif');
  $uploadPath = 'uploads/photos/';

  $fileExtension = pathinfo($uploadedFile['file']['file_name'], PATHINFO_EXTENSION);
  if (!in_array(strtolower($fileExtension), $allowedExtensions)) {
    return "Error: Only JPG, JPEG, PNG, and GIF files are allowed.";
  }

  $uniqueFileName = uniqid('photo_') . '.' . $fileExtension;
  $destinationPath = $uploadPath . $uniqueFileName;

  if (!move_uploaded_file($uploadedFile['file']['tmp_name'], $destinationPath)) {
    return "Error: Failed to move the uploaded file.";
  }

  $data = array('foto' => $uniqueFileName);
  $where = array('nip' => $nip);
  $dbConnection->where($where);
  $dbConnection->update('tbl_pegawai', $data);

  return "Photo uploaded and updated successfully.";
}
```

