Please design a class in C++ to represent a 3D point with floating-point coordinates and define the following operations for two points:
1. Addition: Add two points and return a new point with the sum of their coordinates.
2. Subtraction: Subtract one point from another and return a new point with the difference of their coordinates.
3. Multiplication: Multiply the coordinates of two points and return a new point with the product of their coordinates.
4. Division: Divide the coordinates of one point by another and return a new point with the quotient of their coordinates.
5. Distance: Calculate the Euclidean distance between two points and return the result as a floating-point number.
6. Equality: Check if two points are equal and return a boolean value indicating the result.

The class should also provide the following additional operations:
7. Scaling: Scale the coordinates of a point by a given factor and return a new point with the scaled coordinates.
8. Reflection: Reflect a point across the x-axis, y-axis, or z-axis, and return a new point with the reflected coordinates.
9. Rotation: Rotate a point by a given angle in degrees around the x-axis, y-axis, or z-axis, and return a new point with the rotated coordinates.
10. Translation: Translate a point by a given amount in the x, y, or z directions and return a new point with the translated coordinates.

class Point {
    private:
        float x, y, z;
    public: 
        Point(float x, float y, float z) : x{x}, y{y}, z{z} {};

        Point operator+(const Point& other) const {
            return Point(x + other.x, y + other.y, z + other.z);
        }

        Point operator-(const Point& other) const {
            return Point(x - other.x, y - other.y, z - other.z);
        }

        Point operator*(const Point& other) const {
            return Point(x * other.x, y * other.y, z * other.z);
        }

        Point operator/(const Point& other) const {
            return Point(x / other.x, y / other.y, z / other.z);
        }

        float distanceTo(const Point& other) const {
            float dx = x - other.x;
            float dy = y - other.y;
            float dz = z - other.z;
            return sqrt(dx * dx + dy * dy + dz * dz);
        }

        bool operator==(const Point& other) const {
            return x == other.x && y == other.y && z == other.z;
        }

        Point scale(float factor) const {
            return Point(x * factor, y * factor, z * factor);
        }

        Point reflect(char axis) const {
            if (axis == 'x') {
                return Point(x, -y, -z);
            } else if (axis == 'y') {
                return Point(-x, y, -z);
            } else if (axis == 'z') {
                return Point(-x, -y, z);
            }
            return *this;
        }

        Point rotate(float angle, char axis) const {
            float radian = angle * (M_PI / 180.0);
            if (axis == 'x') {
                float rotatedY = y * cos(radian) - z * sin(radian);
                float rotatedZ = y * sin(radian) + z * cos(radian);
                return Point(x, rotatedY, rotatedZ);
            } else if (axis == 'y') {
                float rotatedX = x * cos(radian) + z * sin(radian);
                float rotatedZ = -x * sin(radian) + z * cos(radian);
                return Point(rotatedX, y, rotatedZ);
            } else if (axis == 'z') {
                float rotatedX = x * cos(radian) - y * sin(radian);
                float rotatedY = x * sin(radian) + y * cos(radian);
                return Point(rotatedX, rotatedY, z);
            }
            return *this;
        }

        Point translate(float tx, float ty, float tz) const {
            return Point(x + tx, y + ty, z + tz);
        }
};

