```java
import java.util.Scanner;
import java.util.HashMap;
import java.util.Map;

public class Signup {
    private static Map<String, String> userCredentials = new HashMap<>();

    /**
     * Shows the signup menus
     */
    public static void signUpUI() {
        Scanner sc = new Scanner(System.in);
        int selection;
        boolean flag = false;

        do {
            System.out.println("Choose what operation you want to perform");
            System.out.println("1. Brand Sign-Up");
            // More menu options can be added here
            System.out.println("0. Exit");

            selection = sc.nextInt();

            switch (selection) {
                case 1:
                    signUp();
                    break;
                case 0:
                    flag = true;
                    break;
                default:
                    System.out.println("Invalid selection. Please try again.");
            }
        } while (!flag);
    }

    /**
     * Handles the signup process by taking input for username and password
     */
    private static void signUp() {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a username: ");
        String username = sc.nextLine();

        if (userCredentials.containsKey(username)) {
            System.out.println("Username already exists. Please choose a different username.");
            signUp();
        } else {
            System.out.println("Enter a password: ");
            String password = sc.nextLine();
            userCredentials.put(username, password);
            System.out.println("Signup successful for username: " + username);
        }
    }
}
```

