script
const minPath = (grid, k) => {
  const n = grid.length;
  const dp = Array.from(new Array(n), () => new Array(n).fill(new Array(k).fill(null)));
  const dirs = [[-1, 0], [0, 1], [1, 0], [0, -1]]; // 4 possible directions: up, right, down, left

  function dfs(x, y, step) {
    if (step === 0) return [];
    if (dp[x][y][step]) return dp[x][y][step]; 

    let bestPath = [Infinity]; 

    for (let [dx, dy] of dirs) { // for each possible direction
      const nx = x + dx; 
      const ny = y + dy; 
      if (nx < 0 || ny < 0 || nx >= n || ny >= n) continue; 

      const path = [grid[nx][ny]].concat(dfs(nx, ny, step - 1)); 
      { // optimize bestPath
        let i = 0;
        while (i < path.length && i < bestPath.length && path[i] === bestPath[i]) 
          i += 1;       
        if (i < path.length && (i === bestPath.length || path[i] < bestPath[i]))
          bestPath = path;
      }
    }

    return dp[x][y][step] = bestPath;
  }

  let startX = 0, startY = 0;
  grid.forEach((row, x) => {
    row.forEach((value, y) => {
      if(value < grid[startX][startY]){
        startX = x;
        startY = y;
      }
    })
  });

  let minimumPath = [grid[startX][startY]].concat(dfs(startX, startY, k - 1));

  return minimumPath;
}

