    for i in range(n, m + 1):
        counts.append(len(divisors(i)))
    return counts

def weighted_average(div_counts, n, m):
    total_sum = sum([count * num for count, num in zip(div_counts, range(n, m + 1))])
    total_count = sum(div_counts)
    return round(total_sum / total_count)

def custom_base_repr(num, base):
    if base < 2 or base > 10:
        return -1

    digits = []
    while num > 0:
        digits.append(str(num % base))
        num //= base

    if base == 2:
        prefix = "0b"
    elif base == 8:
        prefix = "0o"
    else:
        prefix = ""

    return "{}{}".format(prefix, "".join(digits[::-1]))

